{"file_path":"src/scanner.js","content":"/**
 * The scanner. It turns UTF-8 source text into tokens, counting positions in
 * code points, and reports the first thing it cannot scan.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = [
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.'
]

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9'
const isHexDigit = (ch) => isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
const isBinDigit = (ch) => ch === '0' || ch === '1'
const isOctDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '7'
const isIdentStart = (ch) =>
  ch !== undefined && ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_')
const isIdentPart = (ch) => isIdentStart(ch) || isDigit(ch)

class Scanner {
  constructor(source) {
    // Code points, so that a character outside the basic plane counts once.
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }
    return ch
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  scan() {
    while (!this.atEnd()) {
      const ch = this.peek()

      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        this.advance()
        continue
      }

      const line = this.line
      const column = this.column

      if (ch === '/' && this.peek(1) === '/') {
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }

      if (ch === '/' && this.peek(1) === '*') {
        this.blockComment(line, column)
        continue
      }

      if (ch === '"') {
        this.string(line, column)
        continue
      }

      if (ch === 'r' && this.peek(1) === '"') {
        this.rawString(line, column)
        continue
      }

      if (isDigit(ch)) {
        this.number(line, column)
        continue
      }

      if (isIdentStart(ch)) {
        this.identifier(line, column)
        continue
      }

      const two = ch + (this.peek(1) === undefined ? '' : this.peek(1))
      if (TWO_CHAR_PUNCT.includes(two)) {
        this.advance()
        this.advance()
        this.push('punct', two, line, column)
        continue
      }

      if (ONE_CHAR_PUNCT.includes(ch)) {
        this.advance()
        this.push('punct', ch, line, column)
        continue
      }

      this.fail(line, column, `unexpected character ${ch}`)
    }

    return this.tokens
  }

  push(kind, body, line, column) {
    this.tokens.push({ kind, body, line, column })
  }

  blockComment(line, column) {
    this.advance() // '/'
    this.advance() // '*'
    let depth = 1

    while (depth > 0) {
      if (this.atEnd()) {
        this.fail(line, column, 'unterminated block comment')
      }
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

  string(line, column) {
    this.advance() // opening quote
    let value = ''

    for (;;) {
      if (this.atEnd()) {
        this.fail(line, column, 'unterminated string')
      }

      const ch = this.peek()

      if (ch === '\n') {
        this.fail(this.line, this.column, 'newline in string')
      }

      if (ch === '"') {
        this.advance()
        this.push('string', JSON.stringify(value), line, column)
        return
      }

      if (ch !== '\\') {
        value += this.advance()
        continue
      }

      const escLine = this.line
      const escColumn = this.column
      this.advance() // backslash

      if (this.atEnd()) {
        this.fail(line, column, 'unterminated string')
      }

      const marker = this.peek()

      if (marker === '\n') {
        this.fail(this.line, this.column, 'newline in string')
      }

      const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
      if (Object.prototype.hasOwnProperty.call(simple, marker)) {
        this.advance()
        value += simple[marker]
        continue
      }

      if (marker === 'x') {
        this.advance()
        const a = this.peek()
        const b = this.peek(1)
        if (!isHexDigit(a) || !isHexDigit(b)) {
          this.fail(escLine, escColumn, 'invalid escape \\x')
        }
        this.advance()
        this.advance()
        value += String.fromCodePoint(parseInt(a + b, 16))
        continue
      }

      if (marker === 'u') {
        this.advance()
        if (this.peek() !== '{') {
          this.fail(escLine, escColumn, 'invalid escape \\u')
        }
        this.advance()
        let digits = ''
        while (isHexDigit(this.peek())) {
          digits += this.advance()
        }
        if (digits.length === 0 || this.peek() !== '}') {
          this.fail(escLine, escColumn, 'invalid escape \\u')
        }
        const code = parseInt(digits, 16)
        if (code > 0x10ffff) {
          this.fail(escLine, escColumn, 'invalid escape \\u')
        }
        this.advance() // '}'
        value += String.fromCodePoint(code)
        continue
      }

      this.fail(escLine, escColumn, `invalid escape \\${marker}`)
    }
  }

  rawString(line, column) {
    this.advance() // 'r'
    this.advance() // opening quote
    let value = ''

    for (;;) {
      if (this.atEnd()) {
        this.fail(line, column, 'unterminated string')
      }
      const ch = this.advance()
      if (ch === '"') {
        this.push('rawstring', JSON.stringify(value), line, column)
        return
      }
      value += ch
    }
  }

  identifier(line, column) {
    let text = ''
    while (isIdentPart(this.peek())) {
      text += this.advance()
    }
    this.push(isIdentStart(text) && KEYWORDS.has(text) ? 'keyword' : 'ident', text, line, column)
  }

  /** Consumes a run of digits, allowing `_` only between two of them. */
  run(isDigitOf) {
    let text = ''
    while (!this.atEnd()) {
      const ch = this.peek()
      if (isDigitOf(ch)) {
        text += this.advance()
      } else if (ch === '_' && isDigitOf(this.peek(-1)) && isDigitOf(this.peek(1))) {
        text += this.advance()
      } else {
        break
      }
    }
    return text
  }

  /** The scanner stopped; anything word-like still there makes the number bad. */
  finishNumber(text, line, column) {
    if (isIdentPart(this.peek())) {
      this.fail(line, column, `invalid number ${text + this.peek()}`)
    }
    this.push('number', text, line, column)
  }

  number(line, column) {
    const prefix = this.peek() === '0' ? this.peek(1) : undefined
    const bases = {
      x: isHexDigit, X: isHexDigit,
      b: isBinDigit, B: isBinDigit,
      o: isOctDigit, O: isOctDigit
    }

    if (prefix !== undefined && Object.prototype.hasOwnProperty.call(bases, prefix)) {
      let text = this.advance() + this.advance()
      const isDigitOf = bases[prefix]
      if (!isDigitOf(this.peek())) {
        const trailing = isIdentPart(this.peek()) ? this.peek() : ''
        this.fail(line, column, `invalid number ${text + trailing}`)
      }
      text += this.run(isDigitOf)
      this.finishNumber(text, line, column)
      return
    }

    let text = this.run(isDigit)

    if (this.peek() === '.' && isDigit(this.peek(1))) {
      text += this.advance()
      text += this.run(isDigit)
    }

    const exp = this.peek()
    if (exp === 'e' || exp === 'E') {
      const sign = this.peek(1)
      const signed = sign === '+' || sign === '-'
      if (isDigit(sign) || (signed && isDigit(this.peek(2)))) {
        text += this.advance()
        if (signed) text += this.advance()
        text += this.run(isDigit)
      }
    }

    this.finishNumber(text, line, column)
  }
}

export function scan(source) {
  return new Scanner(source).scan()
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
