/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync, writeSync } from 'fs'
import { scan, ScanError, KINDS } from './scanner.js'

/** Writes the whole buffer, so that nothing is lost on a pipe. */
function writeAll(fd, text) {
  const buffer = Buffer.from(text, 'utf8')
  let offset = 0
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EPIPE') return
      throw error
    }
  }
}

function render(mode, tokens) {
  const lines = []

  if (mode === 'tokens') {
    for (const token of tokens) {
      lines.push(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
    }
    return lines.join('')
  }

  const counts = new Map(KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) {
    counts.set(token.kind, counts.get(token.kind) + 1)
  }
  for (const kind of KINDS) {
    lines.push(`${kind} ${counts.get(kind)}\n`)
  }
  lines.push(`total ${tokens.length}\n`)
  return lines.join('')
}

function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    writeAll(2, 'error: usage: cli.js tokens|stats\n')
    process.exitCode = 2
    return
  }

  let source
  try {
    source = readFileSync(0, 'utf8')
  } catch (error) {
    if (error.code === 'EAGAIN' || error.code === 'ENOENT') source = ''
    else throw error
  }

  let tokens
  try {
    tokens = scan(source)
  } catch (error) {
    if (!(error instanceof ScanError)) throw error
    writeAll(2, `error: ${error.line}:${error.column}: ${error.reason}\n`)
    process.exitCode = 2
    return
  }

  writeAll(1, render(args[0], tokens))
  process.exitCode = 0
}

main()
