    this.position++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }
    return ch
  }

  skipWhitespace() {
    while (this.position < this.source.length) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
        this.advance()
      } else {
        break
      }
    }
  }

  skipLineComment() {
    // We're at '/', peek ahead for '/'
    while (this.position < this.source.length && this.peek() !== '\n') {
      this.advance()
    }
  }

  skipBlockComment() {
    let depth = 1
    this.advance() // skip '/'
    this.advance() // skip '*'

    while (this.position < this.source.length && depth > 0) {
      if (this.peek() === '/' && this.peekNext() === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peekNext() === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }

    return depth === 0
  }

  peekNext() {
    return this.source[this.position + 1]
  }

  scanToken() {
    this.skipWhitespace()

    if (this.position >= this.source.length) {
      return true
    }

    const ch = this.peek()

    // Check for comments
    if (ch === '/' && this.peekNext() === '/') {
      this.advance()
      this.advance()
      this.skipLineComment()
      return true
    }

    if (ch === '/' && this.peekNext() === '*') {
      const startLine = this.line
      const startCol = this.column
      if (!this.skipBlockComment()) {
        this.errors.push({ line: startLine, column: startCol, message: 'unterminated block comment' })
        return false
      }
      return true
    }

    const tokenLine = this.line
    const tokenCol = this.column

    // String literal
    if (ch === '"') {
      return this.scanString(tokenLine, tokenCol)
    }

    // Raw string
    if (ch === 'r' && this.peekNext() === '"') {
      return this.scanRawString(tokenLine, tokenCol)
    }

    // Number
    if (this.isDigit(ch)) {
      return this.scanNumber(tokenLine, tokenCol)
    }

    // Identifier or keyword
    if (this.isIdentifierStart(ch)) {
      return this.scanIdentifier(tokenLine, tokenCol)
    }

    // Punctuation
    if (this.isPunctuation(ch)) {
      return this.scanPunctuation(tokenLine, tokenCol)
    }

    // Unexpected character
    this.errors.push({ line: tokenLine, column: tokenCol, message: `unexpected character ${ch}` })
    return false
  }

  scanString(tokenLine, tokenCol) {
    this.advance() // skip opening quote
    let value = ''

    while (this.position < this.source.length) {
      const ch = this.peek()

      if (ch === '\n') {
        this.errors.push({ line: this.line, column: this.column, message: 'newline in string' })
        return false
      }

      if (ch === '"') {
        this.advance()
        this.tokens.push({ kind: 'string', body: JSON.stringify(value), line: tokenLine, column: tokenCol })
        return true
      }

      if (ch === '\\') {
        this.advance()
        if (this.position >= this.source.length) {
          this.errors.push({ line: tokenLine, column: tokenCol, message: 'unterminated string' })
          return false
        }

        const escape = this.peek()
        let escaped = null

        switch (escape) {
          case 'n':
            escaped = '\n'
            break
          case 't':
            escaped = '\t'
            break
          case 'r':
            escaped = '\r'
            break
          case '\\':
            escaped = '\\'
            break
          case '"':
            escaped = '"'
            break
          case '0':
            escaped = '\0'
            break
          case 'x':
            this.advance()
            if (this.position + 1 >= this.source.length) {
              this.errors.push({ line: this.line, column: this.column - 1, message: `invalid escape \\${escape}` })
              return false
            }
            const hex = this.source.substring(this.position, this.position + 2)
            if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
              this.errors.push({ line: this.line, column: this.column, message: `invalid escape \\x${hex}` })
              return false
            }
            escaped = String.fromCharCode(parseInt(hex, 16))
            this.advance()
            this.position++
            value += escaped
            continue
          case 'u':
            this.advance()
            if (this.peek() !== '{') {
              this.errors.push({ line: this.line, column: this.column - 1, message: `invalid escape \\u` })
              return false
            }
            this.advance()
            let hexStr = ''
            while (this.position < this.source.length && this.peek() !== '}') {
              hexStr += this.peek()
              this.advance()
            }
            if (this.position >= this.source.length) {
              this.errors.push({ line: this.line, column: this.column - 1, message: `invalid escape \\u{${hexStr}` })
              return false
            }
            if (!/^[0-9a-fA-F]+$/.test(hexStr) || hexStr.length === 0) {
              this.errors.push({ line: this.line, column: this.column - hexStr.length - 2, message: `invalid escape \\u{${hexStr}` })
              return false
            }
            const codePoint = parseInt(hexStr, 16)
            if (codePoint > 0x10FFFF) {
              this.errors.push({ line: this.line, column: this.column - hexStr.length - 2, message: `invalid escape \\u{${hexStr}}` })
              return false
            }
            escaped = String.fromCodePoint(codePoint)
            this.advance()
            value += escaped
            continue
          default:
            this.errors.push({ line: this.line, column: this.column - 1, message: `invalid escape \\${escape}` })
            return false
        }

        this.advance()
        value += escaped
      } else {
        value += this.advance()
      }
    }

    this.errors.push({ line: tokenLine, column: tokenCol, message: 'unterminated string' })
    return false
  }

  scanRawString(tokenLine, tokenCol) {
    this.advance() // skip 'r'
    this.advance() // skip opening quote
    let value = ''

    while (this.position < this.source.length) {
      const ch = this.peek()

      if (ch === '"') {
        this.advance()
        this.tokens.push({ kind: 'rawstring', body: JSON.stringify(value), line: tokenLine, column: tokenCol })
        return true
      }

      value += this.advance()
    }

    this.errors.push({ line: tokenLine, column: tokenCol, message: 'unterminated string' })
    return false
  }

  scanNumber(tokenLine, tokenCol) {
    let text = ''

    // Check for hex, octal, binary
    if (this.peek() === '0' && (this.peekNext() === 'x' || this.peekNext() === 'X')) {
      text += this.advance() // '0'
      text += this.advance() // 'x' or 'X'

      if (!this.isHexDigit(this.peek())) {
        // Invalid: prefix with no digit
        if (this.position < this.source.length && this.isAlphaOrDigitOrUnderscore(this.peek())) {
          text += this.peek()
          this.errors.push({
            line: tokenLine,
            column: tokenCol,
            message: `invalid number ${text}`
          })
        } else {
          this.errors.push({
            line: tokenLine,
            column: tokenCol,
            message: `invalid number ${text}`
          })
        }
        return false
      }

      while (this.position < this.source.length && (this.isHexDigit(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          // Check if surrounded by hex digits
          if (!this.isHexDigit(this.source[this.position - 1]) || !this.isHexDigit(this.peek(1))) {
            break
          }
        }
        text += this.advance()
      }

      // Check for invalid trailing characters
      if (this.position < this.source.length && (this.isAlphaOrDigitOrUnderscore(this.peek()))) {
        text += this.peek()
        this.errors.push({
          line: tokenLine,
          column: tokenCol,
          message: `invalid number ${text}`
        })
        return false
      }

      this.tokens.push({ kind: 'number', body: text, line: tokenLine, column: tokenCol })
      return true
    }

    if (this.peek() === '0' && (this.peekNext() === 'b' || this.peekNext() === 'B')) {
      text += this.advance() // '0'
      text += this.advance() // 'b' or 'B'

      if (this.peek() !== '0' && this.peek() !== '1') {
        // Invalid: prefix with no digit
        if (this.position < this.source.length && this.isAlphaOrDigitOrUnderscore(this.peek())) {
          text += this.peek()
          this.errors.push({
            line: tokenLine,
            column: tokenCol,
            message: `invalid number ${text}`
          })
        } else {
          this.errors.push({
            line: tokenLine,
            column: tokenCol,
            message: `invalid number ${text}`
          })
        }
        return false
      }

      while (this.position < this.source.length && ((this.peek() === '0' || this.peek() === '1') || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!(this.source[this.position - 1] === '0' || this.source[this.position - 1] === '1') || !(this.peek(1) === '0' || this.peek(1) === '1')) {
            break
          }
        }
        text += this.advance()
      }

      // Check for invalid trailing characters
      if (this.position < this.source.length && (this.isAlphaOrDigitOrUnderscore(this.peek()))) {
        text += this.peek()
        this.errors.push({
          line: tokenLine,
          column: tokenCol,
          message: `invalid number ${text}`
        })
        return false
      }

      this.tokens.push({ kind: 'number', body: text, line: tokenLine, column: tokenCol })
      return true
    }

    if (this.peek() === '0' && (this.peekNext() === 'o' || this.peekNext() === 'O')) {
      text += this.advance() // '0'
      text += this.advance() // 'o' or 'O'

      if (!/[0-7]/.test(this.peek())) {
        // Invalid: prefix with no digit
        if (this.position < this.source.length && this.isAlphaOrDigitOrUnderscore(this.peek())) {
          text += this.peek()
          this.errors.push({
            line: tokenLine,
            column: tokenCol,
            message: `invalid number ${text}`
          })
        } else {
          this.errors.push({
            line: tokenLine,
            column: tokenCol,
            message: `invalid number ${text}`
          })
        }
        return false
      }

      while (this.position < this.source.length && (/[0-7]/.test(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!/[0-7]/.test(this.source[this.position - 1]) || !/[0-7]/.test(this.peek(1))) {
            break
          }
        }
        text += this.advance()
      }

      // Check for invalid trailing characters
      if (this.position < this.source.length && (this.isAlphaOrDigitOrUnderscore(this.peek()))) {
        text += this.peek()
        this.errors.push({
          line: tokenLine,
          column: tokenCol,
          message: `invalid number ${text}`
        })
        return false
      }

      this.tokens.push({ kind: 'number', body: text, line: tokenLine, column: tokenCol })
      return true
    }

    // Decimal number
    while (this.position < this.source.length && (this.isDigit(this.peek()) || this.peek() === '_')) {
      if (this.peek() === '_') {
        if (!this.isDigit(this.source[this.position - 1]) || !this.isDigit(this.peek(1))) {
          break
        }
      }
      text += this.advance()
    }

    // Optional decimal part
    if (this.peek() === '.' && this.isDigit(this.peekNext())) {
      text += this.advance() // '.'
      while (this.position < this.source.length && (this.isDigit(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!this.isDigit(this.source[this.position - 1]) || !this.isDigit(this.peek(1))) {
            break
          }
        }
        text += this.advance()
      }
    }

    // Optional exponent
    if ((this.peek() === 'e' || this.peek() === 'E') && (this.isDigit(this.peekNext()) || ((this.peekNext() === '+' || this.peekNext() === '-') && this.isDigit(this.source[this.position + 2])))) {
      text += this.advance() // 'e' or 'E'
      if (this.peek() === '+' || this.peek() === '-') {
        text += this.advance()
      }
      while (this.position < this.source.length && (this.isDigit(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!this.isDigit(this.source[this.position - 1]) || !this.isDigit(this.peek(1))) {
            break
          }
        }
        text += this.advance()
      }
    }

    // Check for invalid trailing characters
    if (this.position < this.source.length && (this.isAlphaOrDigitOrUnderscore(this.peek()))) {
      text += this.peek()
      this.errors.push({
        line: tokenLine,
        column: tokenCol,
        message: `invalid number ${text}`
      })
      return false
    }

    this.tokens.push({ kind: 'number', body: text, line: tokenLine, column: tokenCol })
    return true
  }

  scanIdentifier(tokenLine, tokenCol) {
    let text = ''

    while (this.position < this.source.length && (this.isIdentifierContinue(this.peek()))) {
      text += this.advance()
    }

    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    this.tokens.push({ kind, body: text, line: tokenLine, column: tokenCol })
    return true
  }

  scanPunctuation(tokenLine, tokenCol) {
    let text = ''

    // Try two-character operators first (longest match first)
    const twoChar = this.peek() + (this.peekNext() || '')
    const twoCharPunct = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']

    if (twoCharPunct.includes(twoChar)) {
      text += this.advance()
      text += this.advance()
      this.tokens.push({ kind: 'punct', body: text, line: tokenLine, column: tokenCol })
      return true
    }

    // Single character punctuation
    const singleChar = this.peek()
    const singleCharPunct = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

    if (singleCharPunct.includes(singleChar)) {
      text += this.advance()
      this.tokens.push({ kind: 'punct', body: text, line: tokenLine, column: tokenCol })
      return true
    }

    // Should not reach here
    this.errors.push({ line: tokenLine, column: tokenCol, message: `unexpected character ${singleChar}` })
    return false
  }

  isDigit(ch) {
    return ch >= '0' && ch <= '9'
  }

  isHexDigit(ch) {
    return this.isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
  }

  isIdentifierStart(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_'
  }

  isIdentifierContinue(ch) {
    return this.isIdentifierStart(ch) || this.isDigit(ch)
  }

  isAlphaOrDigitOrUnderscore(ch) {
    return this.isIdentifierStart(ch) || this.isDigit(ch)
  }

  isPunctuation(ch) {
    return '==!=<=>&&||->=>+-*/%=<>!(){}[],.;.'.includes(ch) || ch === '.'
  }

  scan() {
    while (this.position < this.source.length) {
      if (!this.scanToken()) {
        return false
      }
    }
    return true
  }
}

function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]
  const input = readFileSync(0, 'utf8')

  const scanner = new Scanner(input)
  if (!scanner.scan()) {
    const error = scanner.errors[0]
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.message}\n`)
    process.exit(2)
  }

  if (mode === 'tokens') {
    for (const token of scanner.tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
    }
  } else if (mode === 'stats') {
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0
    }

    for (const token of scanner.tokens) {
      counts[token.kind]++
    }

    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      process.stdout.write(`${kind} ${counts[kind]}\n`)
    }

    const total = Object.values(counts).reduce((a, b) => a + b, 0)
    process.stdout.write(`total ${total}\n`)
  }

  process.exit(0)
}

main()

diffs.newText:
 * tokens by kind.
